begin;
set local search_path=public,extensions;
select plan(30);
select ok((select count(*)=7 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['franchise_crm_prospects','franchise_crm_activities','franchise_pipeline_events','franchise_performance_metric_versions','franchise_performance_score_snapshots','franchise_performance_alerts','franchise_performance_objective_versions'])),'seven CRM and performance records exist');
select ok((select count(*)=7 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['franchise_crm_prospects','franchise_crm_activities','franchise_pipeline_events','franchise_performance_metric_versions','franchise_performance_score_snapshots','franchise_performance_alerts','franchise_performance_objective_versions'])),'RLS covers every CRM and performance table');
select ok((select count(*)=7 from pg_policies where schemaname='public'and tablename=any(array['franchise_crm_prospects','franchise_crm_activities','franchise_pipeline_events','franchise_performance_metric_versions','franchise_performance_score_snapshots','franchise_performance_alerts','franchise_performance_objective_versions'])),'each table has an explicit read policy');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name like'franchise_%'and data_type in('real','double precision')),'scores and objectives never use floating point');
select ok((select count(*)>=4 from information_schema.columns where table_schema='public'and table_name=any(array['franchise_performance_metric_versions','franchise_performance_score_snapshots'])and column_name like'%basis_points%'and data_type='integer'),'scores and weights use integer basis points');
select ok((select count(*)>=2 from information_schema.columns where table_schema='public'and table_name='franchise_performance_objective_versions'and data_type='bigint'),'objective measures use exact bigint values');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and indexname='franchise_performance_metric_active_uidx'),'metric definition has one active version');
select ok((select count(*)=5 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['franchise_crm_activities','franchise_pipeline_events','franchise_performance_metric_versions','franchise_performance_score_snapshots','franchise_performance_objective_versions'])and t.tgname like'%_immutable'and not t.tgisinternal),'activities, transitions, metric versions, scores and objectives are immutable');
select ok((select count(*)=4 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['save_franchise_prospect','record_franchise_activity','advance_franchise_pipeline','record_franchise_performance_snapshot'])),'four hardened server commands exist');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['save_franchise_prospect','record_franchise_activity','advance_franchise_pipeline','record_franchise_performance_snapshot'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anonymous and service roles cannot invoke commands');
select ok((select count(*)=4 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['save_franchise_prospect','record_franchise_activity','advance_franchise_pipeline','record_franchise_performance_snapshot'])),'authenticated has explicit RPC execution');
select ok(not has_table_privilege('authenticated','public.franchise_crm_prospects','INSERT')and not has_table_privilege('authenticated','public.franchise_pipeline_events','DELETE')and not has_table_privilege('authenticated','public.franchise_performance_score_snapshots','INSERT'),'direct CRM and score mutations are denied');
select ok((select pg_get_functiondef(p.oid)like'%FRANCHISE_OWNER%'and pg_get_functiondef(p.oid)like'%FRANCHISE_MANAGER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='franchise_crm_write_access'),'franchise CRM writes require operator roles');
select ok((select pg_get_functiondef(p.oid)like'%territory_version_id%'and pg_get_functiondef(p.oid)like'%t.franchise_id=p_franchise_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='save_franchise_prospect'),'prospects are bound to a territory version of the same franchise');
select ok((select count(*)=1 from pg_constraint where conrelid='public.franchise_crm_prospects'::regclass and contype='u'and pg_get_constraintdef(oid)like'%franchise_id, contact_email, prospect_type%'),'prospect deduplication is franchise scoped');
select ok((select pg_get_functiondef(p.oid)like'%array_position(stages,p_to_stage)<>array_position(stages,p.pipeline_stage)+1%'and pg_get_functiondef(p.oid)like'%INVALID_PIPELINE_TRANSITION%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='advance_franchise_pipeline'),'pipeline only advances through the next standard stage');
select ok((select pg_get_functiondef(p.oid)like'%for update%'and pg_get_functiondef(p.oid)like'%p.row_version<>p_expected_row_version%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='advance_franchise_pipeline'),'pipeline transition locks and checks optimistic version');
select ok((select count(*)=1 from pg_constraint where conrelid='public.franchise_pipeline_events'::regclass and contype='u'and pg_get_constraintdef(oid)like'%prospect_id, idempotency_key%'),'pipeline replay has a durable uniqueness guard');
select ok((select pg_get_functiondef(p.oid)like'%numerator%'and pg_get_functiondef(p.oid)like'%denominator%'and pg_get_functiondef(p.oid)like'%*10000/%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_franchise_performance_snapshot'),'server computes exact KPI ratios from numerator and denominator');
select ok((select pg_get_functiondef(p.oid)like'%score::bigint*weight_basis_points%'and pg_get_functiondef(p.oid)not like'%CLIENT_NETWORK'',2000%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_franchise_performance_snapshot'),'global score uses versioned metric weights rather than hardcoded axis weights');
select ok((select pg_get_functiondef(p.oid)like'%source_evidence_hash%'and pg_get_functiondef(p.oid)like'%measurements_snapshot%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_franchise_performance_snapshot'),'score retains measurement and evidence snapshots');
select ok((select pg_get_functiondef(p.oid)not like'%update public.franchises set status%'and pg_get_functiondef(p.oid)like'%health_suggestion%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_franchise_performance_snapshot'),'score only suggests health and never sanctions automatically');
select ok((select pg_get_functiondef(p.oid)not like'%franchise_entry_fee_ledger_entries%'and pg_get_functiondef(p.oid)not like'%franchise_distribution_ledger_entries%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_franchise_performance_snapshot'),'performance control never creates IT entry-fee debt or financial distribution');
select ok((select count(*)=4 and bool_and(pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%finish_contract_command%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['save_franchise_prospect','record_franchise_activity','advance_franchise_pipeline','record_franchise_performance_snapshot'])),'all commands are canonically idempotent');
select ok((select count(*)=4 and bool_and(pg_get_functiondef(p.oid)like'%audit_events%'and pg_get_functiondef(p.oid)like'%event_outbox%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['save_franchise_prospect','record_franchise_activity','advance_franchise_pipeline','record_franchise_performance_snapshot'])),'all commands emit audit and Outbox evidence');
select ok((select count(*)=6 from pg_indexes where schemaname='public'and indexname=any(array['franchise_prospects_pipeline_idx','franchise_activities_timeline_idx','franchise_pipeline_timeline_idx','franchise_scores_period_idx','franchise_alerts_open_idx','franchise_objectives_active_idx'])),'CRM, scores, alerts and objectives have operational indexes');
select ok(exists(select 1 from pg_constraint where conrelid='public.franchise_performance_score_snapshots'::regclass and contype='c'and pg_get_constraintdef(oid)like'%jsonb_typeof(axis_scores)%'),'axis scores are retained as a structured immutable snapshot');
select ok((select count(*)=6 from unnest(array['CLIENT_NETWORK','LIBRARY_QUALITY','PROVIDER_NETWORK','DELIVERY_PERFORMANCE','CLIENT_SATISFACTION','COMPLIANCE_FINANCE'])),'six controlled performance axes are defined by contract');
select ok((select count(*)=9 from unnest(array['SENT','OPENED','REGISTERED','PROFILE_STARTED','VERIFIED','DIAGNOSTIC_STARTED','OPPORTUNITY_CREATED','RFQ_STARTED','CONTRACT_SIGNED'])),'pipeline contains all nine Gold Master stages');
select ok((select count(*)=1 from pg_constraint where conrelid='public.franchise_performance_score_snapshots'::regclass and contype='u'and pg_get_constraintdef(oid)like'%franchise_id, period_start, period_end, model_version%'),'one score snapshot exists per franchise period and model');
select * from finish();rollback;
